test("canonical correction apply guard requires the production project confirmation", () => {
  assert.doesNotThrow(() =>
    assertCanonicalCorrectionApplyTarget({
      apply: false,
      confirmProject: null,
      supabaseUrl: "https://example.supabase.co",
    }),
  )

  assert.throws(
    () =>
      assertCanonicalCorrectionApplyTarget({
        apply: true,
